import { useState, type FormEvent } from 'react';
import { Alert, Button, Select, Stack, Switch, TextField } from '@jinx-ui/react';

const ROLES = [
  { value: 'admin', label: 'Администратор' },
  { value: 'editor', label: 'Редактор' },
  { value: 'viewer', label: 'Наблюдатель' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invitedEmail, setInvitedEmail] = useState<string | null>(null);

  const isValid = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValid ? 'Адрес должен быть вида name@example.com' : undefined;

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setInvitedEmail(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <Stack direction="column" gap="var(--jx-space-4)">
      {invitedEmail && (
        <Alert
          status="success"
          title="Приглашение отправлено"
          closable
          onClose={() => setInvitedEmail(null)}
        >
          {`Мы пригласили ${invitedEmail} в команду.`}
        </Alert>
      )}

      <form onSubmit={handleSubmit} noValidate>
        <Stack direction="column" gap="var(--jx-space-4)">
          <TextField
            label="Электронная почта"
            type="email"
            name="email"
            value={email}
            placeholder="name@example.com"
            hint="Приглашение придёт на этот адрес и будет действовать 7 дней."
            invalid={Boolean(errorText)}
            error={errorText}
            onChange={(value: string) => setEmail(value)}
            onBlur={() => setTouched(true)}
            required
          />

          <Select
            label="Роль в команде"
            name="role"
            value={role}
            options={ROLES}
            onChange={(value: string) => setRole(value)}
          />

          <Switch
            label="Отправить уведомление"
            checked={notify}
            onChange={(checked: boolean) => setNotify(checked)}
          />

          <Button type="submit" variant="primary" disabled={!isValid}>
            Отправить приглашение
          </Button>
        </Stack>
      </form>
    </Stack>
  );
}

